{"file_text": "@page "/tracking"
@using ShipmentTracker.Client.Models
@rendermode InteractiveAuto
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>Track Shipment</PageTitle>

<h2>Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-20260001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@tracking">
                @(tracking ? "Searching…" : "Track")
            </button>
        </div>
    </div>
</div>

@if (result is not null)
{
    @if (!result.Found)
    {
        <div class="alert alert-warning">@result.Message</div>
    }
    else if (result.Shipment is not null)
    {
        var s = result.Shipment;
        <div class="card">
            <div class="card-header">
                <h5 class="mb-0">Shipment @s.TrackingNumber</h5>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Status</dt>
                            <dd><span class="badge @StatusBadgeClass(s.Status) fs-6">@s.Status</span></dd>
                            <dt>Origin</dt>
                            <dd>@s.Origin</dd>
                            <dt>Destination</dt>
                            <dd>@s.Destination</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Recipient</dt>
                            <dd>@s.RecipientName</dd>
                            <dt>Shipped Date</dt>
                            <dd>@s.ShippedDate.ToString("MMM dd, yyyy")</dd>
                            <dt>Estimated Delivery</dt>
                            <dd>
                                <strong>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</strong>
                                @if (s.EstimatedDelivery.Date >= DateTime.Today)
                                {
                                    var daysLeft = (s.EstimatedDelivery.Date - DateTime.Today).Days;
                                    <span class="text-muted ms-2">
                                        (@(daysLeft == 0 ? "Today" : $"in {daysLeft} day(s)"))
                                    </span>
                                }
                            </dd>
                            <dt>Description</dt>
                            <dd>@s.Description</dd>
                        </dl>
                    </div>
                </div>
            </div>
        </div>
    }
}

<hr class="my-4" />

<h4>My Shipments</h4>
@if (myShipments is null)
{
    <p><em>Loading your shipments…</em></p>
}
else if (!myShipments.Any())
{
    <p class="text-muted">No shipments found for your account.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in myShipments)
                {
                    <tr>
                        <td>@s.TrackingNumber</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @StatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <button class="btn btn-sm btn-outline-primary"
                                    @onclick="() => QuickTrack(s.TrackingNumber)">
                                Details
                            </button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [Inject] private HttpClient Http { get; set; } = default!;

    private string trackingNumber = "";
    private bool tracking;
    private TrackingResult? result;
    private List<ShipmentDto>? myShipments;

    protected override async Task OnInitializedAsync()
    {
        myShipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments/my");
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        tracking = true;
        result = null;
        try
        {
            result = await Http.GetFromJsonAsync<TrackingResult>($"api/shipments/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
        }
        catch
        {
            result = new TrackingResult { Found = false, Message = "An error occurred while tracking." };
        }
        finally
        {
            tracking = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }

    private async Task QuickTrack(string tn)
    {
        trackingNumber = tn;
        await TrackShipment();
    }

    private static string StatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Out for Delivery" => "bg-info text-dark",
        "Pending" => "bg-warning text-dark",
        "Picked Up" => "bg-secondary",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}
