+            <h5>Create Shipment</h5>
+            <div class="row g-2">
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Tracking #" @bind="newShipment.TrackingNumber" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Recipient Name" @bind="newShipment.RecipientName" />
+                </div>
+                <div class="col-md-3 mt-2">
+                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
+                </div>
+                <div class="col-md-3 mt-2">
+                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
+                </div>
+                <div class="col-md-3 mt-2">
+                    <label class="form-label small">Est. Delivery</label>
+                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
+                </div>
+                <div class="col-md-3 mt-2 d-flex align-items-end">
+                    <button class="btn btn-primary" @onclick="CreateShipment" disabled="@creating">
+                        @(creating ? "Creating…" : "Create")
+                    </button>
+                </div>
+            </div>
+            @if (!string.IsNullOrEmpty(createError))
+            {
+                <div class="alert alert-danger mt-2">@createError</div>
+            }
+        </div>
+    </div>
+}
+
+@if (shipments is null)
+{
+    <p><em>Loading shipments…</em></p>
+}
+else if (!FilteredShipments.Any())
+{
+    <p>No shipments match your filters.</p>
+}
+else
+{
+    <div class="table-responsive">
+        <table class="table table-striped table-hover">
+            <thead class="table-dark">
+                <tr>
+                    <th>Tracking #</th>
+                    <th>Origin</th>
+                    <th>Destination</th>
+                    <th>Status</th>
+                    <th>Recipient</th>
+                    <th>Est. Delivery</th>
+                    <th>Actions</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var s in FilteredShipments)
+                {
+                    <tr>
+                        <td><strong>@s.TrackingNumber</strong></td>
+                        <td>@s.Origin</td>
+                        <td>@s.Destination</td>
+                        <td>
+                            <span class="badge @StatusBadgeClass(s.Status)">@s.Status</span>
+                        </td>
+                        <td>@s.RecipientName</td>
+                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
+                        <td>
+                            @if (editingId == s.Id)
+                            {
+                                <select class="form-select form-select-sm d-inline-block w-auto"
+                                        @bind="editStatus">
+                                    @foreach (var st in ShipmentStatuses.All)
+                                    {
+                                        <option value="@st">@st</option>
+                                    }
+                                </select>
+                                <button class="btn btn-sm btn-primary ms-1" @onclick="() => SaveUpdate(s.Id)">Save</button>
+                                <button class="btn btn-sm btn-secondary ms-1" @onclick="CancelEdit">Cancel</button>
+                            }
+                            else
+                            {
+                                <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(s)">Edit</button>
+                            }
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+}
+
+@code {
+    [Inject] private HttpClient Http { get; set; } = default!;
+
+    private List<ShipmentDto>? shipments;
+    private string filterText = "";
+    private string filterStatus = "";
+    private int? editingId;
+    private string editStatus = "";
+
+    private bool showNewForm;
+    private bool creating;
+    private string? createError;
+    private ShipmentDto newShipment = new() { Status = ShipmentStatuses.Pending, EstimatedDelivery = DateTime.Today.AddDays(7) };
+
+    private IEnumerable<ShipmentDto> FilteredShipments =>
+        (shipments ?? [])
+            .Where(s => string.IsNullOrEmpty(filterText) ||
+                        s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
+                        s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase))
+            .Where(s => string.IsNullOrEmpty(filterStatus) || s.Status == filterStatus);
+
+    protected override async Task OnInitializedAsync()
+    {
+        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments");
+    }
+
+    private void StartEdit(ShipmentDto s)
+    {
+        editingId = s.Id;
+        editStatus = s.Status;
+    }
+
+    private void CancelEdit() => editingId = null;
+
+    private async Task SaveUpdate(int id)
+    {
+        var update = new ShipmentUpdateDto { Status = editStatus };
+        var response = await Http.PutAsJsonAsync($"api/shipments/{id}", update);
+        if (response.IsSuccessStatusCode)
+        {
+            var updated = await response.Content.ReadFromJsonAsync<ShipmentDto>();
+            var idx = shipments!.FindIndex(s => s.Id == id);
+            if (idx >= 0 && updated is not null) shipments[idx] = updated;
+            editingId = null;
+        }
+    }
+
+    private void ToggleNewShipmentForm()
+    {
+        showNewForm = !showNewForm;
+        createError = null;
+    }
+
+    private async Task CreateShipment()
+    {
+        creating = true;
+        createError = null;
+        try
+        {
+            var response = await Http.PostAsJsonAsync("api/shipments", newShipment);
+            if (response.IsSuccessStatusCode)
+            {
+                var created = await response.Content.ReadFromJsonAsync<ShipmentDto>();
+                if (created is not null) shipments?.Insert(0, created);
+                newShipment = new() { Status = ShipmentStatuses.Pending, EstimatedDelivery = DateTime.Today.AddDays(7) };
+                showNewForm = false;
+            }
+            else
+            {
+                createError = $"Error: {response.StatusCode}";
+            }
+        }
+        catch (Exception ex)
+        {
+            createError = ex.Message;
+        }
+        finally
+        {
+            creating = false;
+        }
+    }
+
+    private static string StatusBadgeClass(string status) => status switch
+    {
+        "Delivered" => "bg-success",
+        "In Transit" => "bg-primary",
+        "Out for Delivery" => "bg-info text-dark",
+        "Pending" => "bg-warning text-dark",
+        "Picked Up" => "bg-secondary",
+        "Cancelled" => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
+

